-- 1. LIMPIEZA PREVIA SI EXISTEN
DROP VIEW IF EXISTS v_pbi_productos CASCADE;
DROP VIEW IF EXISTS v_pbi_clientes CASCADE;
DROP TABLE IF EXISTS vet_persona CASCADE;
DROP TABLE IF EXISTS vet_producto CASCADE;
DROP TABLE IF EXISTS vet_distrito CASCADE;
DROP TABLE IF EXISTS vet_categoria CASCADE;
DROP TABLE IF EXISTS vet_unidad_medida CASCADE;
DROP TABLE IF EXISTS samar_clientes CASCADE;
DROP TABLE IF EXISTS samar_articulos CASCADE;
DROP TABLE IF EXISTS cliente_consolidado CASCADE;
DROP TABLE IF EXISTS producto_consolidado CASCADE;
DROP TABLE IF EXISTS usuario_web CASCADE;

-- 2. TABLAS CATÃLOGO VETERINARIA
CREATE TABLE vet_distrito (
    iddistrito INT PRIMARY KEY,
    nomdistrito VARCHAR(100) NOT NULL
);

CREATE TABLE vet_categoria (
    idcategoria INT PRIMARY KEY,
    nomcategoria VARCHAR(100) NOT NULL
);

CREATE TABLE vet_unidad_medida (
    idunidad_medida INT PRIMARY KEY,
    nomunidad_medida VARCHAR(100) NOT NULL
);

-- 3. TABLAS TRANSACCIONALES VETERINARIA
CREATE TABLE vet_persona (
    idpersona SERIAL PRIMARY KEY,
    dni VARCHAR(20) NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    ape_paterno VARCHAR(100) NOT NULL,
    ape_materno VARCHAR(100),
    fechnac DATE,
    genero VARCHAR(10) DEFAULT 'M',
    celular VARCHAR(30),
    correo VARCHAR(100),
    direccion VARCHAR(255),
    est_civil VARCHAR(10) DEFAULT 'SO',
    iddistrito INT,
    usucre VARCHAR(50),
    feccre TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    usumod VARCHAR(50),
    fecmod TIMESTAMPTZ,
    estado CHAR(1) DEFAULT '1'
);

CREATE TABLE vet_producto (
    idproducto SERIAL PRIMARY KEY,
    nomproducto VARCHAR(150) NOT NULL,
    descripcion TEXT,
    precio_unitario DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    stock_actual DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    idcategoria INT,
    idunidad_medida INT,
    usucre VARCHAR(50),
    feccre TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    usumod VARCHAR(50),
    fecmod TIMESTAMPTZ,
    estado CHAR(1) DEFAULT '1'
);

-- 4. TABLAS TRANSACCIONALES SAMAR IMPORTADORA
CREATE TABLE samar_clientes (
    id_cliente VARCHAR(50) PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    apellido VARCHAR(100) NOT NULL,
    edad INT,
    estado_civil VARCHAR(50),
    residencia VARCHAR(255),
    origen VARCHAR(255)
);

CREATE TABLE samar_articulos (
    codigo_producto VARCHAR(50) PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL,
    categoria VARCHAR(100),
    precio_unitario DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    costo_unitario DECIMAL(12,2) NOT NULL DEFAULT 0.00
);

-- 5. TABLAS CONSOLIDADAS (ETL DESTINO)
CREATE TABLE cliente_consolidado (
    id_consolidado SERIAL PRIMARY KEY,
    origen_bd VARCHAR(50) NOT NULL,
    id_origen VARCHAR(50) NOT NULL,
    identificacion_dni VARCHAR(50),
    nombre VARCHAR(100),
    apellidos VARCHAR(100),
    genero VARCHAR(30),
    celular VARCHAR(50),
    direccion VARCHAR(255),
    fecha_registro TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_cliente_consolidado UNIQUE (origen_bd, id_origen)
);

CREATE TABLE producto_consolidado (
    id_consolidado SERIAL PRIMARY KEY,
    origen_bd VARCHAR(50) NOT NULL,
    id_origen VARCHAR(50) NOT NULL,
    nombre_producto VARCHAR(150) NOT NULL,
    categoria VARCHAR(100),
    precio DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    stock_o_costo DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    fecha_registro TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_producto_consolidado UNIQUE (origen_bd, id_origen)
);

-- 6. TABLA DE USUARIOS Y ROLES (LOGIN WEB)
CREATE TABLE usuario_web (
    idusuario SERIAL PRIMARY KEY,
    sistema VARCHAR(30) NOT NULL,
    usuario VARCHAR(50) NOT NULL,
    clave_hash VARCHAR(255) NOT NULL,
    nombre VARCHAR(100),
    estado CHAR(1) DEFAULT '1',
    feccre TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    ultimo_acceso TIMESTAMPTZ
);

-- 7. TRIGGERS EN TIEMPO REAL (REPLICACIÃ“N AUTOMÃTICA A CONSOLIDADO)

-- A) Trigger Veterinaria -> cliente_consolidado
CREATE OR REPLACE FUNCTION fn_trg_vet_persona()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO cliente_consolidado (
        origen_bd, id_origen, identificacion_dni, nombre, apellidos, genero, celular, direccion, fecha_registro
    )
    VALUES (
        'VETERINARIA',
        NEW.idpersona::text,
        NEW.dni,
        NEW.nombre,
        TRIM(COALESCE(NEW.ape_paterno, '') || ' ' || COALESCE(NEW.ape_materno, '')),
        CASE WHEN NEW.genero = 'M' THEN 'MASCULINO' ELSE 'FEMENINO' END,
        NEW.celular,
        NEW.direccion,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (origen_bd, id_origen)
    DO UPDATE SET
        identificacion_dni = EXCLUDED.identificacion_dni,
        nombre = EXCLUDED.nombre,
        apellidos = EXCLUDED.apellidos,
        genero = EXCLUDED.genero,
        celular = EXCLUDED.celular,
        direccion = EXCLUDED.direccion,
        fecha_registro = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_vet_persona
AFTER INSERT OR UPDATE ON vet_persona
FOR EACH ROW EXECUTE FUNCTION fn_trg_vet_persona();

-- B) Trigger Veterinaria -> producto_consolidado
CREATE OR REPLACE FUNCTION fn_trg_vet_producto()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO producto_consolidado (
        origen_bd, id_origen, nombre_producto, categoria, precio, stock_o_costo, fecha_registro
    )
    VALUES (
        'VETERINARIA',
        NEW.idproducto::text,
        NEW.nomproducto,
        'GENERAL',
        NEW.precio_unitario,
        NEW.stock_actual,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (origen_bd, id_origen)
    DO UPDATE SET
        nombre_producto = EXCLUDED.nombre_producto,
        categoria = EXCLUDED.categoria,
        precio = EXCLUDED.precio,
        stock_o_costo = EXCLUDED.stock_o_costo,
        fecha_registro = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_vet_producto
AFTER INSERT OR UPDATE ON vet_producto
FOR EACH ROW EXECUTE FUNCTION fn_trg_vet_producto();

-- C) Trigger Samar -> cliente_consolidado
CREATE OR REPLACE FUNCTION fn_trg_samar_clientes()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO cliente_consolidado (
        origen_bd, id_origen, identificacion_dni, nombre, apellidos, genero, celular, direccion, fecha_registro
    )
    VALUES (
        'SAMAR',
        NEW.id_cliente,
        NEW.id_cliente,
        NEW.nombre,
        NEW.apellido,
        'NO ESPECIFICADO',
        NULL,
        NEW.residencia,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (origen_bd, id_origen)
    DO UPDATE SET
        identificacion_dni = EXCLUDED.identificacion_dni,
        nombre = EXCLUDED.nombre,
        apellidos = EXCLUDED.apellidos,
        direccion = EXCLUDED.direccion,
        fecha_registro = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_samar_clientes
AFTER INSERT OR UPDATE ON samar_clientes
FOR EACH ROW EXECUTE FUNCTION fn_trg_samar_clientes();

-- D) Trigger Samar -> producto_consolidado
CREATE OR REPLACE FUNCTION fn_trg_samar_articulos()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO producto_consolidado (
        origen_bd, id_origen, nombre_producto, categoria, precio, stock_o_costo, fecha_registro
    )
    VALUES (
        'SAMAR',
        NEW.codigo_producto,
        NEW.nombre,
        NEW.categoria,
        NEW.precio_unitario,
        NEW.costo_unitario,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (origen_bd, id_origen)
    DO UPDATE SET
        nombre_producto = EXCLUDED.nombre_producto,
        categoria = EXCLUDED.categoria,
        precio = EXCLUDED.precio,
        stock_o_costo = EXCLUDED.stock_o_costo,
        fecha_registro = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_samar_articulos
AFTER INSERT OR UPDATE ON samar_articulos
FOR EACH ROW EXECUTE FUNCTION fn_trg_samar_articulos();

-- 8. VISTAS PARA DIRECTQUERY EN POWER BI
CREATE OR REPLACE VIEW v_pbi_clientes AS
SELECT 
    id_consolidado,
    origen_bd,
    id_origen,
    identificacion_dni,
    nombre,
    apellidos,
    genero,
    celular,
    direccion,
    fecha_registro
FROM cliente_consolidado;

CREATE OR REPLACE VIEW v_pbi_productos AS
SELECT 
    id_consolidado,
    origen_bd,
    id_origen,
    nombre_producto,
    categoria,
    precio,
    stock_o_costo,
    (precio * stock_o_costo) AS valor_inventario,
    fecha_registro
FROM producto_consolidado;

